      echo "all roots applied"
      APPLY
  artifacts:
    name: terragucci-report-apply-wave-2
    when: always
    paths:
      - terragucci-report/

tips:
  stage: tips
  image:
    name: ghcr.io/intentius/terragucci-tofu:0.4.49-tofu1.13.1@sha256:f3a33c6e61f4243d5ba5519830564ad911f5d61a0cb3b0b068c27a6096e6e190
  needs:
    - apply-wave-2
  variables:
    TF_IN_AUTOMATION: '1'
    TF_INPUT: '0'
    TG_TOKEN: '$GITLAB_TOKEN'
    TG_SHA: '$CI_COMMIT_SHA'
    TG_BRANCH: '$CI_DEFAULT_BRANCH'
    GIT_DEPTH: '0'
  rules:
    - if: '$CI_COMMIT_BRANCH == $CI_DEFAULT_BRANCH'
  resource_group: terragucci-tips
  script:
    - |
      bash <<'TIPS' || exit $?
      set -u
      export GITLAB_TOKEN="$TG_TOKEN"
      git remote set-url origin "${CI_SERVER_PROTOCOL}://oauth2:${TG_TOKEN}@${CI_SERVER_FQDN}/${CI_PROJECT_PATH}.git"
      terragucci respond tips --mode apply --binary tofu || true
      TIPS

// Written by terragucci init: each root is a terraform.roots entry, so chant's terraform-apply step can plan and apply it.
// Run terragucci init again after adding or moving a root.
export default {
  "terraform": {
    "roots": {
      "app": {
        "dir": "app"
      },
      "network": {
        "dir": "network"
      }
    },
    "binary": "tofu"
  }
};

